import queue
import threading
from typing import Callable, Any, Optional


class Worker:
    """Background thread worker that processes queue items via a callback."""

    def __init__(
        self,
        handler: Callable[[Any], None],
        input_queue: Optional[queue.Queue] = None,
        is_daemon: bool = True,
        poll_timeout: float = 1.0,
    ):
        self.handler = handler
        self.input_queue = input_queue or queue.Queue()
        self.is_daemon = is_daemon
        self.poll_timeout = poll_timeout
        self._shutdown = threading.Event()
        self._worker_thread = threading.Thread(target=self._worker_loop, daemon=is_daemon)

    def launch(self) -> None:
        """Launch the worker thread."""
        self._worker_thread.start()

    def shutdown(self, join: bool = True) -> None:
        """Stop the worker thread."""
        self._shutdown.set()
        if join:
            self._worker_thread.join(timeout=10)

    def enqueue(self, item: Any) -> None:
        """Push an item onto the queue."""
        self.input_queue.put(item)

    def _worker_loop(self) -> None:
        """Process items from queue until shutdown."""
        while not self._shutdown.is_set():
            try:
                item = self.input_queue.get(timeout=self.poll_timeout)
                try:
                    self.handler(item)
                finally:
                    self.input_queue.task_done()
            except queue.Empty:
                pass
            except Exception as err:
                print(f"Handler failed: {err}")


if __name__ == "__main__":
    def handle_item(x):
        print(f"Handled: {x}")

    w = Worker(handle_item)
    w.launch()

    for j in range(5):
        w.enqueue(j)

    w.input_queue.join()
    w.shutdown()
